#include "elevsim.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <inttypes.h>
#include <stdarg.h>
#include <errno.h>
#include <limits.h>

void pcg32_seed(Pcg32*p,uint64_t seed){p->state=0;p->inc=(UINT64_C(54)<<1)|1;p->has_normal=false;(void)pcg32_next(p);p->state+=seed;(void)pcg32_next(p);}
uint32_t pcg32_next(Pcg32*p){uint64_t old=p->state;p->state=old*UINT64_C(6364136223846793005)+p->inc;uint32_t x=(uint32_t)(((old>>18)^old)>>27),rot=(uint32_t)(old>>59);return (x>>rot)|(x<<((-rot)&31));}
double pcg_uniform(Pcg32*p){return (double)pcg32_next(p)/4294967296.0;}
uint32_t pcg_bounded(Pcg32*p,uint32_t bound){if(!bound)return 0;uint32_t threshold=(uint32_t)(0u-bound)%bound;for(;;){uint32_t r=pcg32_next(p);if(r>=threshold)return r%bound;}}
bool pcg_bernoulli(Pcg32*p,double q){if(q<=0)return false;if(q>=1)return true;return pcg_uniform(p)<q;}
int pcg_weighted(Pcg32*p,const double*w,size_t n){double sum=0;for(size_t i=0;i<n;i++)if(w[i]>0&&isfinite(w[i]))sum+=w[i];if(!(sum>0)||!isfinite(sum))return -1;double x=pcg_uniform(p)*sum,acc=0;int last=-1;for(size_t i=0;i<n;i++)if(w[i]>0){last=(int)i;acc+=w[i];if(x<acc)return (int)i;}return last;}
double pcg_exponential(Pcg32*p,double lambda){return -log(1.0-pcg_uniform(p))/lambda;}
uint32_t pcg_poisson(Pcg32*p,double lambda){if(lambda<=0)return 0;if(lambda<30){double L=exp(-lambda),q=1;uint32_t k=0;do{k++;q*=pcg_uniform(p);}while(q>L);return k-1;}double slam=sqrt(lambda),loglam=log(lambda),b=0.931+2.53*slam,a=-0.059+0.02483*b,inv_alpha=1.1239+1.1328/(b-3.4),vr=0.9277-3.6224/(b-2);for(;;){double u=pcg_uniform(p)-0.5,v=pcg_uniform(p),us=0.5-fabs(u);if(us<=0)continue;double kd=floor((2.0*a/us+b)*u+lambda+0.43);if(kd<0||kd>UINT32_MAX)continue;if(us>=0.07&&v<=vr)return (uint32_t)kd;if(us<0.013&&v>us)continue;double lhs=log(v*inv_alpha/(a/(us*us)+b));double rhs=-lambda+kd*loglam-lgamma(kd+1.0);if(lhs<=rhs)return (uint32_t)kd;}}
double pcg_normal(Pcg32*p){if(p->has_normal){p->has_normal=false;return p->normal_cache;}double u1;do{u1=pcg_uniform(p);}while(u1<=0);double u2=pcg_uniform(p),r=sqrt(-2.0*log(u1)),th=2.0*3.141592653589793238462643383279502884*u2;p->normal_cache=r*sin(th);p->has_normal=true;return r*cos(th);}
bool pcg_trunc_normal(Pcg32*p,double mean,double sigma,double lo,double hi,double*out){for(uint32_t i=0;i<1000000;i++){double x=mean+sigma*pcg_normal(p);if(x>=lo&&x<=hi){*out=x;return true;}}return false;}

void trace_init(Trace*t){memset(t,0,sizeof*t);}void trace_free(Trace*t){if(!t)return;for(size_t i=0;i<t->n;i++)free(t->p[i].segment);free(t->p);free(t->canonical);memset(t,0,sizeof*t);}
bool trace_import_row_allowed(uint64_t id,EsError*e){if(id>ES_MAX_PASSENGERS){es_error(e,5,0,"trace exceeds 2,000,000 passengers");return false;}return true;}
bool trace_generated_count_allowed(size_t n,EsError*e){if(n>ES_MAX_PASSENGERS){es_error(e,8,0,"generated trace exceeds 2,000,000 passengers");return false;}return true;}
static bool trace_push(Trace*t,Passenger p,EsError*e){if(t->n>=ES_MAX_PASSENGERS){es_error(e,8,0,"trace exceeds 2,000,000 passengers");return false;}if(t->n==t->cap){size_t nc=t->cap?t->cap*2:1024;if(nc>ES_MAX_PASSENGERS)nc=ES_MAX_PASSENGERS;Passenger*q=es_realloc(t->p,nc*sizeof*q,e);if(!q)return false;t->p=q;t->cap=nc;}t->p[t->n++]=p;return true;}
typedef struct{unsigned char*b;size_t n,cap;} Buf;
static bool badd(Buf*b,const char*s,size_t n,EsError*e){if(b->n+n+1>b->cap){size_t nc=b->cap?b->cap:4096;while(nc<b->n+n+1){if(nc>SIZE_MAX/2){es_error(e,8,0,"buffer too large");return false;}nc*=2;}unsigned char*q=es_realloc(b->b,nc,e);if(!q)return false;b->b=q;b->cap=nc;}memcpy(b->b+b->n,s,n);b->n+=n;b->b[b->n]=0;return true;}
static bool bprintf(Buf*b,EsError*e,const char*fmt,...){char small[512];va_list ap;va_start(ap,fmt);int n=vsnprintf(small,sizeof small,fmt,ap);va_end(ap);if(n<0)return false;if((size_t)n<sizeof small)return badd(b,small,(size_t)n,e);char*tmp=es_malloc((size_t)n+1,e);if(!tmp)return false;va_start(ap,fmt);vsnprintf(tmp,(size_t)n+1,fmt,ap);va_end(ap);bool ok=badd(b,tmp,(size_t)n,e);free(tmp);return ok;}
static bool bcsv(Buf*b,const char*s,EsError*e){bool q=false;for(const char*p=s;*p;p++)if(*p==','||*p=='"'||*p=='\r'||*p=='\n'){q=true;break;}if(!q)return badd(b,s,strlen(s),e);if(!badd(b,"\"",1,e))return false;for(const char*p=s;*p;p++){if(*p=='"'&&!badd(b,"\"",1,e))return false;if(!badd(b,p,1,e))return false;}return badd(b,"\"",1,e);}
bool trace_build_canonical(Trace*t,EsError*e){free(t->canonical);t->canonical=NULL;t->canonical_n=0;Buf b={0};const char*h="passenger_id,arrival_us,origin_floor,destination_floor,segment_id\n";if(!badd(&b,h,strlen(h),e)){free(b.b);return false;}for(size_t i=0;i<t->n;i++){Passenger*p=&t->p[i];if(!bprintf(&b,e,"%" PRIu32 ",%" PRIu64 ",%d,%d,",p->id,p->arrival_us,p->origin,p->dest)||!bcsv(&b,p->segment,e)||!badd(&b,"\n",1,e)){free(b.b);return false;}}t->canonical=b.b;t->canonical_n=b.n;t->fingerprint=es_fnv1a64(t->canonical,t->canonical_n);return true;}
static bool csv5(char*line,char**f,EsError*e,int lineno){int col=0;char*p=line;while(col<5){if(!*p&&col<4){es_error(e,5,lineno,"missing CSV column");return false;}char*out=p;f[col++]=out;if(*p=='"'){p++;out=f[col-1]=p;char*w=p;bool closed=false;while(*p){if(*p=='"'){if(p[1]=='"'){*w++='"';p+=2;continue;}closed=true;p++;break;}if(*p=='\r'||*p=='\n'){es_error(e,5,lineno,"multiline CSV field unsupported");return false;}*w++=*p++;}if(!closed){es_error(e,5,lineno,"unterminated CSV quote");return false;}*w=0;if(col<5){if(*p!=','){es_error(e,5,lineno,"junk after quoted field");return false;}p++;}else if(*p){es_error(e,5,lineno,"extra CSV column");return false;}}else{char*comma=strchr(p,',');if(col<5){if(!comma){es_error(e,5,lineno,"missing CSV column");return false;}*comma=0;p=comma+1;}else{if(comma){es_error(e,5,lineno,"extra CSV column");return false;}p+=strlen(p);}}}if(*p){es_error(e,5,lineno,"extra CSV data");return false;}return true;}
static bool u64dec(const char*s,uint64_t*out){if(!*s)return false;uint64_t x=0;for(const char*p=s;*p;p++){if(*p<'0'||*p>'9')return false;unsigned d=(unsigned)(*p-'0');if(x>(UINT64_MAX-d)/10)return false;x=x*10+d;}*out=x;return true;}
static bool idec(const char*s,int*out){if(!*s)return false;char*ep;errno=0;long x=strtol(s,&ep,10);if(errno||*ep||x<INT32_MIN||x>INT32_MAX)return false;*out=(int)x;return true;}
bool trace_import(const char*path,const Config*c,Trace*t,EsError*e){trace_init(t);unsigned char*d;size_t n;if(!es_read_file(path,&d,&n,e,5))return false;if(!es_utf8_valid(d,n,true)){free(d);es_error(e,5,1,"trace invalid UTF-8");return false;}char*buf=es_malloc(n+1,e);if(!buf){free(d);return false;}size_t j=0;for(size_t i=0;i<n;i++){if(d[i]=='\r'&&i+1<n&&d[i+1]=='\n')continue;buf[j++]=(char)d[i];}buf[j]=0;free(d);char*cur=buf;int line=1;char*nl=strchr(cur,'\n');if(nl)*nl=0;if(strcmp(cur,"passenger_id,arrival_us,origin_floor,destination_floor,segment_id")){free(buf);es_error(e,5,1,"trace header mismatch");return false;}cur=nl?nl+1:NULL;uint32_t expect=1;uint64_t prev_arr=0;while(cur&&*cur){nl=strchr(cur,'\n');if(nl)*nl=0;size_t L=strlen(cur);if(L&&cur[L-1]=='\r')cur[--L]=0;line++;if(!*cur){free(buf);trace_free(t);es_error(e,5,line,"blank row");return false;}char*f[5];if(!csv5(cur,f,e,line)){free(buf);trace_free(t);return false;}uint64_t id64,arr;int o,de;if(!u64dec(f[0],&id64)||id64!=expect||id64>UINT32_MAX||!u64dec(f[1],&arr)||!idec(f[2],&o)||!idec(f[3],&de)){free(buf);trace_free(t);es_error(e,5,line,"invalid trace integer/id sequence");return false;}if(!trace_import_row_allowed(id64,e)){free(buf);trace_free(t);e->line=line;return false;}size_t sn=strlen(f[4]);if(sn<1||sn>128||strchr(f[4],'\r')||strchr(f[4],'\n')||!es_utf8_valid((unsigned char*)f[4],sn,true)){free(buf);trace_free(t);es_error(e,5,line,"invalid segment_id");return false;}uint64_t tick=(uint64_t)c->tick_ms*1000;if(arr%tick||arr>(uint64_t)c->duration_s*1000000||o<1||o>c->floors||de<1||de>c->floors||o==de||!config_any_car_serves(c,o,de)||(expect>1&&arr<prev_arr)){free(buf);trace_free(t);es_error(e,5,line,"trace semantic/order violation");return false;}Passenger p={0};p.id=(uint32_t)id64;p.arrival_us=arr;p.origin=o;p.dest=de;p.dir=de>o?1:-1;p.segment=es_strdup(f[4],e);p.state=P_NOT_ARRIVED;p.car=-1;p.group_id=-1;if(!p.segment||!trace_push(t,p,e)){free(p.segment);free(buf);trace_free(t);return false;}prev_arr=arr;expect++;cur=nl?nl+1:NULL;}free(buf);if(!trace_build_canonical(t,e)){trace_free(t);return false;}return true;}
static uint64_t round_even_us(double seconds){double x=seconds*1000000.0;if(x<=0)return 0;double fl=floor(x),fr=x-fl;uint64_t a=(uint64_t)fl;if(fr>0.5)return a+1;if(fr<0.5)return a;return (a&1)?a+1:a;}
static uint64_t visible(const Config*c,double seconds){uint64_t raw=round_even_us(seconds),tick=(uint64_t)c->tick_ms*1000;return es_ceil_div_u64(raw,tick)*tick;}
static bool sample_od_matrix(Pcg32*r,const Config*c,const double*od,int*o,int*d){int n=c->floors*c->floors;int idx=pcg_weighted(r,od,(size_t)n);if(idx<0)return false;*o=idx/c->floors+1;*d=idx%c->floors+1;return true;}
static bool sample_weighted_od(Pcg32*r,const Config*c,const double*ow,const double*dw,int*o,int*d){double oe[ES_MAX_FLOORS],de[ES_MAX_FLOORS];for(int i=0;i<c->floors;i++){bool viable=false;if(ow[i]>0)for(int j=0;j<c->floors;j++)if(j!=i&&dw[j]>0&&config_any_car_serves(c,i+1,j+1)){viable=true;break;}oe[i]=viable?ow[i]:0;}int oi=pcg_weighted(r,oe,(size_t)c->floors);if(oi<0)return false;for(int j=0;j<c->floors;j++)de[j]=(j!=oi&&config_any_car_serves(c,oi+1,j+1))?dw[j]:0;int di=pcg_weighted(r,de,(size_t)c->floors);if(di<0)return false;*o=oi+1;*d=di+1;return true;}
static bool sample_fixed_origin(Pcg32*r,const Config*c,int o,const double*dw,int*d){double de[ES_MAX_FLOORS];for(int j=0;j<c->floors;j++)de[j]=(j+1!=o&&config_any_car_serves(c,o,j+1))?dw[j]:0;int di=pcg_weighted(r,de,(size_t)c->floors);if(di<0)return false;*d=di+1;return true;}
static bool sample_fixed_dest(Pcg32*r,const Config*c,int d,const double*ow,int*o){double oe[ES_MAX_FLOORS];for(int i=0;i<c->floors;i++)oe[i]=(i+1!=d&&config_any_car_serves(c,i+1,d))?ow[i]:0;int oi=pcg_weighted(r,oe,(size_t)c->floors);if(oi<0)return false;*o=oi+1;return true;}
static bool segment_od(Pcg32*r,const Config*c,const SegmentCfg*s,int*o,int*d){if(s->od)return sample_od_matrix(r,c,s->od,o,d);switch(s->profile){case PROF_UP:if(pcg_bernoulli(r,s->lobby_p)){*o=c->lobby;return sample_fixed_origin(r,c,*o,s->w1,d);}return sample_weighted_od(r,c,s->w2,s->w3,o,d);case PROF_DOWN:if(pcg_bernoulli(r,s->lobby_p)){*d=c->lobby;return sample_fixed_dest(r,c,*d,s->w1,o);}return sample_weighted_od(r,c,s->w2,s->w3,o,d);case PROF_INTER:return sample_weighted_od(r,c,s->w1,s->w2,o,d);case PROF_MIXED:{double w[3]={s->upf,s->downf,s->interf};int k=pcg_weighted(r,w,3);if(k==0){*o=c->lobby;return sample_fixed_origin(r,c,*o,s->w1,d);}if(k==1){*d=c->lobby;return sample_fixed_dest(r,c,*d,s->w2,o);}return sample_weighted_od(r,c,s->w3,s->w4,o,d);}case PROF_BURST:return sample_weighted_od(r,c,s->w1,s->w2,o,d);}return false;}
typedef struct{uint64_t arrival;int o,d;size_t seg;uint32_t local;} GRow;
static int grow_cmp(const void*A,const void*B){const GRow*a=A,*b=B;if(a->arrival<b->arrival)return -1;if(a->arrival>b->arrival)return 1;if(a->seg<b->seg)return -1;if(a->seg>b->seg)return 1;return a->local<b->local?-1:a->local>b->local;}
bool trace_generate(const Config*c,Trace*t,EsError*e){trace_init(t);Pcg32 r;pcg32_seed(&r,c->seed);GRow*rows=NULL;size_t n=0,cap=0;for(size_t si=0;si<c->seg_n;si++){const SegmentCfg*s=&c->segments[si];uint32_t local=0;if(s->profile==PROF_BURST){double lo=s->center_s-s->window_s/2.0,hi=s->center_s+s->window_s/2.0;for(uint32_t k=0;k<s->count;k++,local++){if(!trace_generated_count_allowed(n+1,e)){free(rows);return false;}double g;if(!strcmp(s->distribution,"uniform_window"))g=lo+pcg_uniform(&r)*(hi-lo);else if(!pcg_trunc_normal(&r,(double)s->center_s,s->sigma_s,lo,hi,&g)){free(rows);es_error(e,8,0,"truncated normal rejection limit");return false;}int o,d;if(!segment_od(&r,c,s,&o,&d)){free(rows);es_error(e,8,0,"OD sampler failed");return false;}if(n==cap){size_t nc=cap?cap*2:1024;if(nc>ES_MAX_PASSENGERS)nc=ES_MAX_PASSENGERS;GRow*q=es_realloc(rows,nc*sizeof*q,e);if(!q){free(rows);return false;}rows=q;cap=nc;}rows[n++]=(GRow){visible(c,g),o,d,si,local};}}else if(s->rate>0){double g=s->start_s,lambda=s->rate/60.0;for(;;){g+=pcg_exponential(&r,lambda);if(g>=s->end_s)break;if(!trace_generated_count_allowed(n+1,e)){free(rows);return false;}int o,d;if(!segment_od(&r,c,s,&o,&d)){free(rows);es_error(e,8,0,"OD sampler failed");return false;}if(n==cap){size_t nc=cap?cap*2:1024;if(nc>ES_MAX_PASSENGERS)nc=ES_MAX_PASSENGERS;GRow*q=es_realloc(rows,nc*sizeof*q,e);if(!q){free(rows);return false;}rows=q;cap=nc;}rows[n++]=(GRow){visible(c,g),o,d,si,local++};}}}qsort(rows,n,sizeof*rows,grow_cmp);for(size_t i=0;i<n;i++){Passenger p={0};p.id=(uint32_t)(i+1);p.arrival_us=rows[i].arrival;p.origin=rows[i].o;p.dest=rows[i].d;p.dir=p.dest>p.origin?1:-1;p.segment=es_strdup(c->segments[rows[i].seg].id,e);p.state=P_NOT_ARRIVED;p.car=-1;p.group_id=-1;if(!p.segment||!trace_push(t,p,e)){free(p.segment);free(rows);trace_free(t);return false;}}free(rows);if(!trace_build_canonical(t,e)){trace_free(t);return false;}return true;}
bool trace_write(const Trace*t,const char*path,EsError*e){FILE*f=fopen(path,"wb");if(!f){es_error(e,7,0,"cannot open output '%s'",path);return false;}bool ok=es_write_all(f,t->canonical,t->canonical_n);if(fflush(f)||fclose(f))ok=false;if(!ok)es_error(e,7,0,"trace output write failed '%s'",path);return ok;}
bool trace_info_write(const Trace*t,const Config*c,const char*path,const char*mode,EsError*e){FILE*f=fopen(path,"wb");if(!f){es_error(e,7,0,"cannot open output '%s'",path);return false;}fprintf(f,"{\n  \"seed\": %" PRIu64 ",\n  \"passenger_count\": %zu,\n  \"first_arrival_us\": ",c->seed,t->n);if(t->n)fprintf(f,"%" PRIu64,t->p[0].arrival_us);else fputs("null",f);fputs(",\n  \"last_arrival_us\": ",f);if(t->n)fprintf(f,"%" PRIu64,t->p[t->n-1].arrival_us);else fputs("null",f);fprintf(f,",\n  \"trace_fingerprint\": \"%016" PRIx64 "\",\n  \"source_mode\": \"%s\"\n}\n",t->fingerprint,mode);bool ok=!ferror(f)&&fflush(f)==0&&fclose(f)==0;if(!ok)es_error(e,7,0,"trace info write failed");return ok;}
